package com.termux.app.workspace;
import android.app.*;import android.widget.*;import org.junit.*;import static org.junit.Assert.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.*;import java.util.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk=28) public class AgentSpeechServiceTest {
 static class Engine implements DictationBackend,DictationBackend.Factory {
  Listener listener;int starts,stops,cancels,creates;RuntimeException createFailure,startFailure;
  public DictationBackend create(){creates++;if(createFailure!=null)throw createFailure;return this;}
  public void start(Listener l){listener=l;starts++;if(startFailure!=null)throw startFailure;}
  public void stop(){stops++;}public void cancel(){cancels++;}
 }
 static void configure(Activity a){Shadows.shadowOf((Application)a.getApplication()).grantPermissions(android.Manifest.permission.RECORD_AUDIO);}
 @Test public void partialIsPreviewAndFinalAppendsOnlyOnceWithoutExternalActivity(){Activity a=Robolectric.buildActivity(Activity.class).setup().get();configure(a);Engine e=new Engine();EditText input=new EditText(a);input.setText("draft");input.setSelection(0,input.length());List<String> notices=new ArrayList<>(),states=new ArrayList<>();AgentDictation d=new AgentDictation(a,input,()->"one",notices::add,e);d.presentation((text,active,stop,cancel)->states.add(text));d.start();d.start();assertEquals(1,e.starts);assertNull(Shadows.shadowOf(a).getNextStartedActivityForResult());DictationBackend.Listener listener=e.listener;listener.ready();listener.partial("first");listener.partial("first words");assertEquals("draft",input.getText().toString());assertTrue(states.get(states.size()-1).contains("first words"));d.stop();assertEquals(1,e.stops);listener.result("first words");listener.result("duplicate");assertEquals("draft first words",input.getText().toString());assertEquals(1,e.cancels);assertTrue(notices.isEmpty());}
 @Test public void errorCancelSwitchAndEditedDraftRetainText(){Activity a=Robolectric.buildActivity(Activity.class).setup().get();configure(a);Engine e=new Engine();EditText input=new EditText(a);input.setText("keep");String[] owner={"one"};List<String> notices=new ArrayList<>();AgentDictation d=new AgentDictation(a,input,()->owner[0],notices::add,e);d.start();DictationBackend.Listener old=e.listener;d.clear();d.start();old.result("late");assertEquals("keep",input.getText().toString());e.listener.error("microphone: AudioRecord.read=-3");assertEquals(1,notices.size());assertTrue(notices.get(0).contains("AudioRecord.read=-3"));assertEquals("keep",input.getText().toString());d.start();owner[0]="two";d.ownerChanged();e.listener.result("wrong chat");assertEquals("keep",input.getText().toString());d.start();input.setText("edited");e.listener.result("discard");assertEquals("edited",input.getText().toString());d.start();d.background();e.listener.result("hidden");assertEquals("edited",input.getText().toString());}
 @Test public void permissionComesFirstAndDuplicateGrantStartsOneCapture(){Activity a=Robolectric.buildActivity(Activity.class).setup().get();Engine e=new Engine();EditText input=new EditText(a);input.setText("keep");List<String> notices=new ArrayList<>();AgentDictation d=new AgentDictation(a,input,()->"one",notices::add,e);Shadows.shadowOf((Application)a.getApplication()).denyPermissions(android.Manifest.permission.RECORD_AUDIO);d.start();assertEquals(0,e.creates);org.robolectric.shadows.ShadowActivity.PermissionsRequest requested=Shadows.shadowOf(a).getLastRequestedPermission();assertEquals(AgentDictation.AUDIO_REQUEST,requested.requestCode);assertArrayEquals(new String[]{android.Manifest.permission.RECORD_AUDIO},requested.requestedPermissions);d.permissionResult(AgentDictation.AUDIO_REQUEST);assertEquals(0,e.starts);assertTrue(notices.get(0).contains("PERMISSION_DENIED=-1"));d.start();configure(a);d.permissionResult(AgentDictation.AUDIO_REQUEST);d.permissionResult(AgentDictation.AUDIO_REQUEST);assertEquals(1,e.starts);e.listener.result(" ");assertEquals("keep",input.getText().toString());assertEquals(2,notices.size());}
 @Test public void synchronousCreateAndStartFailuresRetainDraft(){Activity a=Robolectric.buildActivity(Activity.class).setup().get();configure(a);Engine e=new Engine();EditText input=new EditText(a);input.setText("draft");List<String> notices=new ArrayList<>();AgentDictation d=new AgentDictation(a,input,()->"one",notices::add,e);e.createFailure=new UnsupportedOperationException();d.start();assertTrue(notices.get(0).contains("UnsupportedOperationException"));assertEquals(0,e.starts);e.createFailure=null;e.startFailure=new IllegalStateException();d.start();assertTrue(notices.get(1).contains("IllegalStateException"));assertEquals(1,e.cancels);assertEquals("draft",input.getText().toString());}
 @Test public void switchingWhilePermissionPendingDoesNotStartOldCapture(){Activity a=Robolectric.buildActivity(Activity.class).setup().get();Shadows.shadowOf((Application)a.getApplication()).denyPermissions(android.Manifest.permission.RECORD_AUDIO);Engine e=new Engine();EditText input=new EditText(a);input.setText("keep");String[] owner={"one"};AgentDictation d=new AgentDictation(a,input,()->owner[0],message->fail(message),e);d.start();owner[0]="two";d.ownerChanged();configure(a);d.permissionResult(AgentDictation.AUDIO_REQUEST);assertEquals(0,e.creates);assertEquals("keep",input.getText().toString());}
}
